@startuml

class User {
  + userId : int
  + name : string
  + address : string
  + birthday : date
}

abstract class BusinessOwner {
  + linkedinAccount : string
}

abstract class HungryCustomer {
  + deliveryAddress : string
}

abstract class Entertainer {
  + stageName : string
  + bio : string
  + pricePer30Min : double
}

class PizzaRestaurant {
  + zipCode : string
  + address : string
  + phoneNumber : string
  + website : string
  + openingHours : string
}

class Pizza {
  + name : string
  + crustStructure : string
  + price : double
}

class Order {
  + orderId : int
  + orderDateTime : datetime
  + latestDeliveryTime : time
  + numberOfPeople : int
}

class EntertainmentOrder {
  + entertainmentType : string
  + duration : int
}

class Availability {
  + day : string
}

User --|> BusinessOwner
User --|> HungryCustomer
User --|> Entertainer

BusinessOwner "1" *-- "1..*" PizzaRestaurant
PizzaRestaurant "1" *-- "1..*" Pizza

HungryCustomer "1" -- "0..*" Order
Order "1" *-- "1..*" Pizza

Order "1" -- "0..1" EntertainmentOrder
EntertainmentOrder "*" -- "1" Entertainer

Entertainer "1" -- "*" Availability
Availability "*" -- "1" PizzaRestaurant

@enduml

